{
    vin = vin.Trim().ToUpperInvariant();
    var m = await db.BankCarMortages.FirstOrDefaultAsync(x => x.OrgId == t.OrgId && x.VIN == vin);
    if (m is null) return Results.NotFound(new { vin });
    m.FlagActive = m.FlagActive == "1" ? "0" : "1";
