        .Select(c => new { c.VIN, c.ModelCode }).ToListAsync();
    return Results.Ok(new { m.DlvMinutesNo, m.TransporterCode, m.ConfirmStatus, m.Remark, m.ConfirmDate, count = cars.Count, cars });
}).RequireAuthorization();

