// ===== Báo cáo bảo lãnh đến hạn thanh toán (port 1:1 FrmBLDenHanThanhToan) — tái dùng BankGuarantee =====
app.MapGet("/api/report/bldenhan", async (AppDbContext db, ITenantContext t, DateTime? from, DateTime? to) =>
{
    if (from is null) return Results.BadRequest(new { error = "Phải chọn ngày báo cáo từ" });
    var toDate = to ?? DateTime.Today;
    if (toDate.Date > DateTime.Today) return Results.BadRequest(new { error = "Ngày kết thúc bảo lãnh đến không được lớn hơn ngày hiện tại!" });
    var f = from.Value.Date; var e = toDate.Date.AddDays(1);
    // BL đến hạn = ngày hết hạn (DateExpired) rơi vào [from, to], đã duyệt, chưa tất toán.
    var recs = await db.BankGuarantees.Where(g => g.OrgId == t.OrgId && g.Status == "Approved" && g.FlagSettled != "1"
                    && g.DateExpired != null && g.DateExpired >= f && g.DateExpired < e).ToListAsync();
    var detail = recs.OrderBy(g => g.DateExpired).Select(g => new
    {
        g.GuaranteeNo, g.DealerCode, g.BankCode, g.BankGuaranteeNo, g.TotalAmount,
        dateExpired = g.DateExpired!.Value.ToString("yyyy-MM-dd"),
        daysLeft = (int)(g.DateExpired!.Value.Date - DateTime.Today).TotalDays
    }).ToList();
    var byBank = recs.GroupBy(g => string.IsNullOrEmpty(g.BankCode) ? "(chưa rõ)" : g.BankCode)
        .Select(g => new { bankCode = g.Key, count = g.Count(), totalAmount = g.Sum(x => x.TotalAmount) })
        .OrderByDescending(x => x.totalAmount).ToList();
    return Results.Ok(new { total = detail.Count, totalAmount = recs.Sum(g => g.TotalAmount), byBank, detail });
}).RequireAuthorization();

// ===== Báo cáo dư nợ bảo lãnh (port 1:1 FrmBaocaoBaolanh) — tái dùng BankGuarantee, gom theo NH + trạng thái =====
app.MapGet("/api/report/guarantee", async (AppDbContext db, ITenantContext t, string? grtNo, DateTime? openFrom, DateTime? openTo, string? bank) =>
{
    var q = db.BankGuarantees.Where(g => g.OrgId == t.OrgId);
    if (!string.IsNullOrWhiteSpace(grtNo)) q = q.Where(g => g.GuaranteeNo.Contains(grtNo!) || g.BankGuaranteeNo.Contains(grtNo!));
    if (!string.IsNullOrWhiteSpace(bank)) q = q.Where(g => g.BankCode == bank);
    if (openFrom is not null) q = q.Where(g => g.DateOpen != null && g.DateOpen >= openFrom.Value.Date);
    if (openTo is not null) q = q.Where(g => g.DateOpen != null && g.DateOpen < openTo.Value.Date.AddDays(1));
    var recs = await q.ToListAsync();
    // Dư nợ BL = tổng giá trị BL đã duyệt, CHƯA tất toán.
    decimal Debit(BankGuarantee g) => g.Status == "Approved" && g.FlagSettled != "1" ? g.TotalAmount : 0;
    var byBank = recs.GroupBy(g => string.IsNullOrEmpty(g.BankCode) ? "(chưa rõ)" : g.BankCode)
        .Select(g => new { bankCode = g.Key, count = g.Count(), totalAmount = g.Sum(x => x.TotalAmount), debit = g.Sum(Debit), settled = g.Count(x => x.FlagSettled == "1") })
        .OrderByDescending(x => x.debit).ToList();
    var byStatus = recs.GroupBy(g => g.Status)
        .Select(g => new { status = g.Key, count = g.Count(), totalAmount = g.Sum(x => x.TotalAmount) })
        .OrderByDescending(x => x.count).ToList();
    var detail = recs.OrderByDescending(g => g.DateOpen).Take(500).Select(g => new
    {
        g.GuaranteeNo, g.DealerCode, g.BankCode, g.BankGuaranteeNo, g.TotalAmount, g.Status, g.FlagSettled,
        dateOpen = g.DateOpen != null ? g.DateOpen.Value.ToString("yyyy-MM-dd") : "",
        debit = Debit(g)
    }).ToList();
    return Results.Ok(new { total = recs.Count, totalDebit = recs.Sum(Debit), totalAmount = recs.Sum(g => g.TotalAmount), byBank, byStatus, detail });
}).RequireAuthorization();

// Cập nhật ngày mốc SO theo lô (port 1:1 FrmMng_SO_Approved_Date, 2010.HTC): ngày duyệt / hết hạn nghĩa vụ cọc / hết hạn BL / đến hạn giao xe.
app.MapGet("/api/salesorders/sodates", async (AppDbContext db, ITenantContext t, string? dealer, string? so) =>
{
    var q = db.SalesOrders.Where(o => o.OrgId == t.OrgId);
    if (!string.IsNullOrWhiteSpace(dealer)) q = q.Where(o => o.DealerCode == dealer);
    if (!string.IsNullOrWhiteSpace(so)) q = q.Where(o => o.SoCode.Contains(so!));
    var items = await q.OrderByDescending(o => o.Id).Take(500).Select(o => new {
        o.SoCode, o.DealerCode, o.Status, o.ApprovedDate, o.DepositDutyEndDate, o.GrtEndDate, o.CarDueDate, o.PenalizeActual
    }).ToListAsync();
    return Results.Ok(new { count = items.Count, totalPenalize = items.Sum(x => x.PenalizeActual), items });
}).RequireAuthorization();

app.MapPost("/api/salesorders/edit-dates", async (SoEditDatesDto dto, AppDbContext db, ITenantContext t) =>
{
    var lines = (dto.Lines ?? new()).Where(l => !string.IsNullOrWhiteSpace(l.SOCode)).ToList();
    if (lines.Count == 0) return Results.BadRequest(new { error = "Không có SO thay đổi." });
    foreach (var l in lines)
        if (l.DepositDutyEndDate.HasValue && l.CarDueDate.HasValue && l.CarDueDate < l.DepositDutyEndDate)
            return Results.BadRequest(new { error = $"SO {l.SOCode}: ngày đến hạn giao xe phải >= ngày hết hạn nghĩa vụ cọc." });
    var codes = lines.Select(l => l.SOCode!.Trim()).ToHashSet();
    var orders = await db.SalesOrders.Where(o => o.OrgId == t.OrgId && codes.Contains(o.SoCode)).ToListAsync();
    var byCode = orders.ToDictionary(o => o.SoCode, o => o);
    int updated = 0; var notFound = new List<string>();
    foreach (var l in lines)
    {
        var code = l.SOCode!.Trim();
        if (!byCode.TryGetValue(code, out var o)) { notFound.Add(code); continue; }
        if (l.ApprovedDate.HasValue) o.ApprovedDate = l.ApprovedDate;
        if (l.DepositDutyEndDate.HasValue) o.DepositDutyEndDate = l.DepositDutyEndDate;
        if (l.GrtEndDate.HasValue) o.GrtEndDate = l.GrtEndDate;
        if (l.CarDueDate.HasValue) o.CarDueDate = l.CarDueDate;
        updated++;
    }
    await db.SaveChangesAsync();
    return Results.Ok(new { updated, notFound = notFound.Distinct().Take(20) });
}).RequireAuthorization();

// Cập nhật tiền phạt trả chậm thực tế theo SO (port 1:1 FrmUpdatePenaltyPmtDelayReal, 2010.HTC).
app.MapPost("/api/salesorders/edit-penalty", async (SoEditPenaltyDto dto, AppDbContext db, ITenantContext t) =>
{
    var lines = (dto.Lines ?? new()).Where(l => !string.IsNullOrWhiteSpace(l.SOCode)).ToList();
    if (lines.Count == 0) return Results.BadRequest(new { error = "Không có SO thay đổi." });
    if (lines.Any(l => l.PenalizeActual < 0)) return Results.BadRequest(new { error = "Tiền phạt không được âm." });
    var codes = lines.Select(l => l.SOCode!.Trim()).ToHashSet();
    var orders = await db.SalesOrders.Where(o => o.OrgId == t.OrgId && codes.Contains(o.SoCode)).ToListAsync();
    var byCode = orders.ToDictionary(o => o.SoCode, o => o);
    int updated = 0; var notFound = new List<string>();
    foreach (var l in lines)
    {
        var code = l.SOCode!.Trim();
        if (!byCode.TryGetValue(code, out var o)) { notFound.Add(code); continue; }
        o.PenalizeActual = l.PenalizeActual; updated++;
    }
    await db.SaveChangesAsync();
    return Results.Ok(new { updated, totalPenalize = orders.Sum(o => o.PenalizeActual), notFound = notFound.Distinct().Take(20) });
}).RequireAuthorization();

// ===== Báo cáo bán hàng đại lý (port 1:1 FrmBanHangDL) — tái dùng SalesOrder + SalesOrderLine =====
app.MapGet("/api/report/salesbydealer", async (AppDbContext db, ITenantContext t, string? dealer, string? status, string? orderType, DateTime? from, DateTime? to) =>
{
    var q = db.SalesOrders.Where(o => o.OrgId == t.OrgId);
    if (!string.IsNullOrWhiteSpace(dealer)) q = q.Where(o => o.DealerCode == dealer);
    if (!string.IsNullOrWhiteSpace(status)) q = q.Where(o => o.Status == status);
    if (!string.IsNullOrWhiteSpace(orderType)) q = q.Where(o => o.OrderType == orderType);
    if (from is not null) q = q.Where(o => o.CreatedAt >= from.Value.Date);
    if (to is not null) q = q.Where(o => o.CreatedAt < to.Value.Date.AddDays(1));
    var orders = await q.ToListAsync();
    var ids = orders.Select(o => o.Id).ToHashSet();
    var lines = await db.SalesOrderLines.Where(l => l.OrgId == t.OrgId && ids.Contains(l.SalesOrderId)).ToListAsync();
    var lineByOrder = lines.GroupBy(l => l.SalesOrderId).ToDictionary(g => g.Key, g => g.ToList());
    int ReqQty(long oid) => lineByOrder.TryGetValue(oid, out var ls) ? ls.Sum(x => x.RequestedQuantity) : 0;
    int AppQty(long oid) => lineByOrder.TryGetValue(oid, out var ls) ? ls.Sum(x => x.ApprovedQuantity ?? 0) : 0;
    decimal Amount(long oid) => lineByOrder.TryGetValue(oid, out var ls) ? ls.Sum(x => x.UnitPrice * x.RequestedQuantity) : 0;
    var byDealer = orders.GroupBy(o => string.IsNullOrEmpty(o.DealerCode) ? "(chưa rõ)" : o.DealerCode)
        .Select(g => new { dealerCode = g.Key, orders = g.Count(), reqQty = g.Sum(o => ReqQty(o.Id)), appQty = g.Sum(o => AppQty(o.Id)), amount = g.Sum(o => Amount(o.Id)) })
        .OrderByDescending(x => x.amount).ToList();
    var byStatus = orders.GroupBy(o => o.Status).Select(g => new { status = g.Key, count = g.Count() }).OrderByDescending(x => x.count).ToList();
    var detail = orders.OrderByDescending(o => o.Id).Take(500).Select(o => new
    {
        o.SoCode, o.DealerCode, o.OrderType, o.PayType, o.Status, createdAt = o.CreatedAt.ToString("yyyy-MM-dd"),
        reqQty = ReqQty(o.Id), appQty = AppQty(o.Id), amount = Amount(o.Id)
    }).ToList();
    return Results.Ok(new { totalOrders = orders.Count, totalReqQty = orders.Sum(o => ReqQty(o.Id)), totalAmount = orders.Sum(o => Amount(o.Id)), byDealer, byStatus, detail });
}).RequireAuthorization();

// ===== Báo cáo tổng hợp (port 1:1 FrmBaoCaoTongHop) — dashboard gộp các entity chính, tái dùng =====
app.MapGet("/api/report/summary", async (AppDbContext db, ITenantContext t) =>
{
    var org = t.OrgId;
    // Đơn hàng bán
    var so = await db.SalesOrders.Where(o => o.OrgId == org).Select(o => o.Status).ToListAsync();
    var soLineAmt = await db.SalesOrderLines.Where(l => l.OrgId == org).SumAsync(l => (decimal?)(l.UnitPrice * l.RequestedQuantity)) ?? 0;
    // Bán buôn ĐL->ĐL
    var ws = await db.WholesaleDeals.Where(w => w.OrgId == org).Select(w => new { w.Status, w.TotalAmount }).ToListAsync();
    // Bảo lãnh ngân hàng
    var grt = await db.BankGuarantees.Where(g => g.OrgId == org).Select(g => new { g.Status, g.FlagSettled, g.TotalAmount }).ToListAsync();
    // Phiếu thanh toán
    var pm = await db.BankPayments.Where(p => p.OrgId == org).Select(p => new { p.PaymentStatus, p.TotalAmount }).ToListAsync();
    // Hợp đồng đại lý bán lẻ
    var dc = await db.DlrContracts.Where(c => c.OrgId == org).CountAsync();
    // Back-order
    var bo = await db.BackOrders.Where(b => b.OrgId == org).Select(b => new { b.QtyOrder, b.QtyDelivered }).ToListAsync();

    var summary = new
    {
        salesOrders = new { count = so.Count, byStatus = so.GroupBy(s => s).Select(g => new { status = g.Key, count = g.Count() }).ToList(), totalAmount = soLineAmt },
        wholesaleDeals = new { count = ws.Count, confirmed = ws.Count(w => w.Status == "Confirmed"), totalAmount = ws.Sum(w => w.TotalAmount) },
        guarantees = new { count = grt.Count, approved = grt.Count(g => g.Status == "Approved"), debit = grt.Where(g => g.Status == "Approved" && g.FlagSettled != "1").Sum(g => g.TotalAmount), settled = grt.Count(g => g.FlagSettled == "1") },
        payments = new { count = pm.Count, approved = pm.Count(p => p.PaymentStatus == "Approved"), totalAmount = pm.Sum(p => p.TotalAmount) },
        dealerContracts = new { count = dc },
        backOrder = new { totalOrder = bo.Sum(b => b.QtyOrder), totalDelivered = bo.Sum(b => b.QtyDelivered), backOrder = bo.Sum(b => b.QtyOrder - b.QtyDelivered) }
    };
    return Results.Ok(summary);
}).RequireAuthorization();

// ===== Báo cáo tình trạng hiệu lực bảo lãnh (port 1:1 FrmBCTinhTrangHoSoHieuLucBaoLanh) — tái dùng BankGuarantee =====
app.MapGet("/api/report/grtvalidity", async (AppDbContext db, ITenantContext t, string? bank, int? soonDays) =>
{
    var soon = soonDays is > 0 ? soonDays.Value : 30;   // ngưỡng "sắp hết hạn" (mặc định 30 ngày)
    var q = db.BankGuarantees.Where(g => g.OrgId == t.OrgId && g.Status == "Approved" && g.FlagSettled != "1");
    if (!string.IsNullOrWhiteSpace(bank)) q = q.Where(g => g.BankCode == bank);
    var recs = await q.ToListAsync();
    var today = DateTime.Today;
    string Classify(BankGuarantee g)
    {
        if (g.DateExpired is null) return "NoDate";
        var days = (g.DateExpired.Value.Date - today).Days;
        if (days < 0) return "Expired";
        if (days <= soon) return "ExpiringSoon";
        return "Valid";
    }
    var detail = recs.OrderBy(g => g.DateExpired ?? DateTime.MaxValue).Take(500).Select(g => new
    {
        g.GuaranteeNo, g.DealerCode, g.BankCode, g.BankGuaranteeNo, g.TotalAmount,
        dateExpired = g.DateExpired != null ? g.DateExpired.Value.ToString("yyyy-MM-dd") : "",
        daysLeft = g.DateExpired != null ? (int)(g.DateExpired.Value.Date - today).TotalDays : (int?)null,
        validity = Classify(g)
    }).ToList();
    var byValidity = recs.GroupBy(Classify)
        .Select(g => new { validity = g.Key, count = g.Count(), totalAmount = g.Sum(x => x.TotalAmount) }).ToList();
    return Results.Ok(new
    {
        soonDays = soon,
        total = recs.Count,
        valid = recs.Count(g => Classify(g) == "Valid"),
        expiringSoon = recs.Count(g => Classify(g) == "ExpiringSoon"),
        expired = recs.Count(g => Classify(g) == "Expired"),
        byValidity, detail
    });
}).RequireAuthorization();

// ===== Báo cáo phiếu thanh toán ngân hàng (port 1:1 báo cáo Pmt_PM) — tái dùng BankPayment =====
app.MapGet("/api/report/payment", async (AppDbContext db, ITenantContext t, string? bank, string? status, string? dealer, DateTime? from, DateTime? to) =>
{
