app.MapPost("/api/servicecampaigns", async (ServiceCampaignDto dto, AppDbContext db, ITenantContext t) =>
{
    var no = (dto.CamNo ?? "").Trim();
    if (no == "") return Results.BadRequest(new { error = "Thiếu số chiến dịch (CamNo)." });
    if (await db.ServiceCampaigns.AnyAsync(c => c.OrgId == t.OrgId && c.CamNo == no))
        return Results.BadRequest(new { error = "Số chiến dịch đã tồn tại: " + no });
    var parts = (dto.Parts ?? new List<ServiceCampaignPartDto>());
    // Guard: mã PT trùng trong 1 chiến dịch + % hợp lệ (0..100).
    var seen = new HashSet<string>(StringComparer.OrdinalIgnoreCase);
    foreach (var p in parts)
    {
        var pc = (p.PartCode ?? "").Trim();
        if (pc == "") return Results.BadRequest(new { error = "Có dòng phụ tùng thiếu mã." });
        if (!seen.Add(pc)) return Results.BadRequest(new { error = "Mã phụ tùng trùng trong chiến dịch: " + pc });
        if (p.PercentDiscount < 0 || p.PercentDiscount > 100) return Results.BadRequest(new { error = "% giảm không hợp lệ cho " + pc });
    }
    var c2 = new ServiceCampaign { OrgId = t.OrgId, CamNo = no, CamName = dto.CamName, CamDesc = dto.CamDesc,
        ConditionDealer = dto.ConditionDealer, StartDate = dto.StartDate, EndDate = dto.EndDate, Status = "Draft" };
    db.ServiceCampaigns.Add(c2); await db.SaveChangesAsync();
    foreach (var p in parts)
        db.ServiceCampaignParts.Add(new ServiceCampaignPart { OrgId = t.OrgId, ServiceCampaignId = c2.Id,
            PartCode = (p.PartCode ?? "").Trim(), PartName = p.PartName, PercentDiscount = p.PercentDiscount });
    await db.SaveChangesAsync();
    return Results.Ok(new { c2.Id, c2.CamNo, c2.Status, partCount = parts.Count });
}).RequireAuthorization();

app.MapGet("/api/servicecampaigns/{id}/parts", async (long id, AppDbContext db, ITenantContext t) =>
{
    var c = await db.ServiceCampaigns.FirstOrDefaultAsync(x => x.OrgId == t.OrgId && x.Id == id);
    if (c is null) return Results.NotFound(new { id });
    var parts = await db.ServiceCampaignParts.Where(p => p.OrgId == t.OrgId && p.ServiceCampaignId == id)
        .OrderBy(p => p.PartCode).Select(p => new { p.PartCode, p.PartName, p.PercentDiscount }).ToListAsync();
    return Results.Ok(new { c.CamNo, c.CamName, c.Status, parts });
}).RequireAuthorization();

app.MapPost("/api/servicecampaigns/{id}/status", async (long id, ServiceCampaignStatusDto dto, AppDbContext db, ITenantContext t) =>
{
    var c = await db.ServiceCampaigns.FirstOrDefaultAsync(x => x.OrgId == t.OrgId && x.Id == id);
    if (c is null) return Results.NotFound(new { id });
    var s = (dto.Status ?? "").Trim();
    if (s != "Draft" && s != "Active" && s != "Closed") return Results.BadRequest(new { error = "Trạng thái không hợp lệ." });
    if (s == "Active" && !await db.ServiceCampaignParts.AnyAsync(p => p.OrgId == t.OrgId && p.ServiceCampaignId == id))
        return Results.BadRequest(new { error = "Chiến dịch chưa có phụ tùng, không thể kích hoạt." });
    c.Status = s; await db.SaveChangesAsync();
    return Results.Ok(new { c.Id, c.Status });
}).RequireAuthorization();

// ===== Gửi SMS + log (SmsSend — port 1:1 FrmSendSMS, TCMotor) — tích hợp SmsTemplate + ServiceCustomer =====
// Chuẩn hóa SĐT VN (giống CUtilsSMS.StdPhoneNo): giữ chữ số, chấp nhận 0xxxxxxxxx (10 số) hoặc +84/84xxxxxxxxx.
static string? StdPhoneVn(string? raw)
{
    if (string.IsNullOrWhiteSpace(raw)) return null;
    var digits = new string(raw.Where(char.IsDigit).ToArray());
    if (digits.StartsWith("84") && digits.Length == 11) digits = "0" + digits.Substring(2);
    if (digits.Length == 10 && digits[0] == '0') return digits;
    return null;
}
app.MapGet("/api/smssends", async (AppDbContext db, ITenantContext t, string? mobile, string? status, string? batch) =>
{
    var q = db.SmsSends.Where(x => x.OrgId == t.OrgId);
    if (!string.IsNullOrWhiteSpace(mobile)) q = q.Where(x => x.Mobile.Contains(mobile!));
    if (!string.IsNullOrWhiteSpace(status)) q = q.Where(x => x.Status == status);
    if (!string.IsNullOrWhiteSpace(batch)) q = q.Where(x => x.BatchNo == batch);
    var items = await q.OrderByDescending(x => x.Id).Take(500)
        .Select(x => new { x.BatchNo, x.Mobile, x.SmsType, x.Contents, x.Status, sendDate = x.SendDate.ToString("yyyy-MM-dd HH:mm") }).ToListAsync();
    return Results.Ok(new { count = items.Count, sent = items.Count(i => i.Status == "Sent"), invalid = items.Count(i => i.Status == "Invalid"), items });
}).RequireAuthorization();

// Gửi SMS: nội dung = smsType (mẫu) hoặc content trực tiếp; SĐT = danh sách mobiles và/hoặc toAllCustomers.
app.MapPost("/api/smssends", async (SmsSendDto dto, AppDbContext db, ITenantContext t) =>
{
    var content = dto.Content?.Trim() ?? "";
    string? smsType = null;
    if (!string.IsNullOrWhiteSpace(dto.SmsType))
    {
        smsType = dto.SmsType.Trim().ToUpperInvariant();
        var tpl = await db.SmsTemplates.FirstOrDefaultAsync(x => x.OrgId == t.OrgId && x.SmsType == smsType && x.FlagActive == "1");
        if (tpl is null) return Results.BadRequest(new { error = $"Không tìm thấy mẫu SMS đang bật cho loại {smsType}." });
        content = tpl.SmsBody;
    }
    if (string.IsNullOrWhiteSpace(content)) return Results.BadRequest(new { error = "Chưa có nội dung SMS (chọn mẫu hoặc nhập nội dung)." });
    var mobiles = new List<string>(dto.Mobiles ?? new());
    if (dto.ToAllCustomers == true)
    {
        var custMobiles = await db.ServiceCustomers.Where(c => c.OrgId == t.OrgId && c.Mobile != null && c.Mobile != "").Select(c => c.Mobile!).ToListAsync();
        mobiles.AddRange(custMobiles);
    }
    if (mobiles.Count == 0) return Results.BadRequest(new { error = "Chưa có số điện thoại nhận." });
    var no = "SMS" + DateTime.Now.ToString("yyMMddHHmmss");
    int sent = 0, invalid = 0;
    var invalids = new List<string>();
    var seen = new HashSet<string>();
    foreach (var m in mobiles)
    {
        var std = StdPhoneVn(m);
        if (std is null) { invalid++; invalids.Add(m); db.SmsSends.Add(new SmsSend { OrgId = t.OrgId, BatchNo = no, Mobile = m ?? "", SmsType = smsType, Contents = content, Status = "Invalid" }); continue; }
        if (!seen.Add(std)) continue; // bỏ trùng số trong lô
        db.SmsSends.Add(new SmsSend { OrgId = t.OrgId, BatchNo = no, Mobile = std, SmsType = smsType, Contents = content, Status = "Sent" });
        sent++;
    }
    await db.SaveChangesAsync();
    return Results.Ok(new { batchNo = no, sent, invalid, invalids, contentLength = content.Length });
}).RequireAuthorization();

// ===== Gửi email + log (EmailSend — port 1:1 FrmSendEmail, TCMotor) — tích hợp EmailTemplate + ServiceCustomer =====
// Kiểm tra định dạng email cơ bản (giống ràng buộc gửi mail WinForm): có @ + tên miền có dấu chấm.
static bool IsValidEmail(string? raw)
{
    if (string.IsNullOrWhiteSpace(raw)) return false;
    var s = raw.Trim();
    var at = s.IndexOf('@');
    if (at <= 0 || at != s.LastIndexOf('@') || at == s.Length - 1) return false;
    var dom = s.Substring(at + 1);
    return dom.Contains('.') && !dom.StartsWith('.') && !dom.EndsWith('.') && !s.Contains(' ');
}

