}).RequireAuthorization();

// ===== Sao kê ngân hàng (BankStatementLine — port 1:1 FrmBank_BankStatement, TCMotor/Sales/Payment) =====
// Import Excel sao kê (bulk add, dedup TransactionCode trong lô) → đối soát (reconcile) với mã thanh toán DMS.
app.MapGet("/api/bankstatements", async (AppDbContext db, ITenantContext t, string? q, string? bankReceive, string? match, string? dateFrom, string? dateTo) =>
{
    var qry = db.BankStatementLines.Where(x => x.OrgId == t.OrgId);
    if (!string.IsNullOrWhiteSpace(q)) qry = qry.Where(x => x.RemittanceDetail!.Contains(q) || x.TransactionCode!.Contains(q) || x.BStatementNo.Contains(q) || x.PaymentCodeDMS!.Contains(q));
    if (!string.IsNullOrWhiteSpace(bankReceive)) qry = qry.Where(x => x.BankReceiveCode == bankReceive);
    if (!string.IsNullOrWhiteSpace(match)) qry = qry.Where(x => x.MatchStatus == match);
    if (!string.IsNullOrWhiteSpace(dateFrom)) qry = qry.Where(x => x.TransactionDate!.CompareTo(dateFrom) >= 0);
    if (!string.IsNullOrWhiteSpace(dateTo)) qry = qry.Where(x => x.TransactionDate!.CompareTo(dateTo) <= 0);
    var items = await qry.OrderByDescending(x => x.Id).Take(500).Select(x => new {
        x.Id, x.BStatementNo, x.TransactionDate, x.TransactionCode, x.DebitVal, x.CreditVal, x.BalanceVal,
        x.RemittanceDetail, x.BankReceiveCode, x.AccountReceiveNo, x.AccountSendName, x.PaymentCodeDMS, x.MatchStatus, x.FlagTnxType
    }).ToListAsync();
    var totDebit = items.Sum(x => x.DebitVal); var totCredit = items.Sum(x => x.CreditVal);
    var matched = items.Count(x => x.MatchStatus == "Y");
    return Results.Ok(new { count = items.Count, totDebit, totCredit, matched, unmatched = items.Count - matched, items });
}).RequireAuthorization();

app.MapPost("/api/bankstatements/import", async (BankStatementImportDto dto, AppDbContext db, ITenantContext t) =>
{
    var no = (dto.BStatementNo ?? "").Trim();
    if (string.IsNullOrWhiteSpace(no)) return Results.BadRequest(new { error = "BStatementNo bắt buộc" });
    var lines = dto.Lines ?? new List<BankStatementRowDto>();
    if (lines.Count == 0) return Results.BadRequest(new { error = "Phải có ít nhất 1 dòng sao kê" });
    // dedup TransactionCode trong lô (guard dup-in-file)
    var seen = new HashSet<string>(StringComparer.OrdinalIgnoreCase);
    var dups = new List<string>();
    foreach (var l in lines)
    {
        var tc = (l.TransactionCode ?? "").Trim();
        if (!string.IsNullOrEmpty(tc) && !seen.Add(tc)) dups.Add(tc);
    }
    if (dups.Count > 0) return Results.BadRequest(new { error = "Trùng mã giao dịch trong lô: " + string.Join(", ", dups.Distinct().Take(10)) });
    // bỏ dòng đã tồn tại trong DB theo TransactionCode (skip-duplicate-neutral)
    var existing = await db.BankStatementLines.Where(x => x.OrgId == t.OrgId && seen.Contains(x.TransactionCode!)).Select(x => x.TransactionCode!).ToListAsync();
    var existSet = new HashSet<string>(existing, StringComparer.OrdinalIgnoreCase);
    int added = 0, skipped = 0;
    var now = DateTime.Now;
    foreach (var l in lines)
    {
        var tc = (l.TransactionCode ?? "").Trim();
        if (!string.IsNullOrEmpty(tc) && existSet.Contains(tc)) { skipped++; continue; }
        db.BankStatementLines.Add(new BankStatementLine {
            OrgId = t.OrgId, BStatementNo = no, TransactionDate = l.TransactionDate, TransactionCode = tc,
            DebitVal = l.DebitVal, CreditVal = l.CreditVal, BalanceVal = l.BalanceVal,
            RemittanceDetail = l.RemittanceDetail, BankSendCode = l.BankSendCode, AccountSendName = l.AccountSendName, AccountSendNo = l.AccountSendNo,
            BankReceiveCode = l.BankReceiveCode, AccountReceiveName = l.AccountReceiveName, AccountReceiveNo = l.AccountReceiveNo,
            ActVoucherCode = l.ActVoucherCode, FlagTnxType = l.FlagTnxType, DealerSendCode = l.DealerSendCode, DealerReceiveCode = l.DealerReceiveCode,
            MatchStatus = "N", CreatedAt = now
        });
        added++;
    }
    await db.SaveChangesAsync();
    return Results.Ok(new { bStatementNo = no, added, skipped });
}).RequireAuthorization();

// Đối soát: gán mã thanh toán DMS cho 1 dòng → MatchStatus='Y' (bỏ trống mã = huỷ đối soát)
app.MapPost("/api/bankstatements/{id}/match", async (long id, BankStatementMatchDto dto, AppDbContext db, ITenantContext t) =>
{
    var r = await db.BankStatementLines.FirstOrDefaultAsync(x => x.OrgId == t.OrgId && x.Id == id);
    if (r is null) return Results.NotFound(new { id });
    var code = (dto.PaymentCodeDMS ?? "").Trim();
    r.PaymentCodeDMS = string.IsNullOrEmpty(code) ? null : code;
    r.MatchStatus = string.IsNullOrEmpty(code) ? "N" : "Y";
    await db.SaveChangesAsync();
    return Results.Ok(new { r.Id, r.PaymentCodeDMS, r.MatchStatus });
}).RequireAuthorization();

app.MapDelete("/api/bankstatements/{id}", async (long id, AppDbContext db, ITenantContext t) =>
{
    var r = await db.BankStatementLines.FirstOrDefaultAsync(x => x.OrgId == t.OrgId && x.Id == id);
    if (r is null) return Results.NotFound(new { id });
    db.BankStatementLines.Remove(r);
    await db.SaveChangesAsync();
    return Results.Ok(new { deleted = id });
}).RequireAuthorization();

// ===== Định mức khuyến mãi hội viên (CustomerPromotion — port 1:1 FrmMember, TCMotor/Customer) =====
app.MapGet("/api/custpromotions", async (AppDbContext db, ITenantContext t, string? card, string? program) =>
{
    var q = db.CustomerPromotions.Where(x => x.OrgId == t.OrgId);
    if (!string.IsNullOrWhiteSpace(card)) q = q.Where(x => x.CardNo == card);
    if (!string.IsNullOrWhiteSpace(program)) q = q.Where(x => x.ProgramCode == program);
    var items = await q.OrderBy(x => x.CardNo).ThenBy(x => x.ProgramCode).Take(500).Select(x => new
    {
        x.Id, x.CardNo, x.ProgramCode, x.ProgramName, effDate = x.EffDate.HasValue ? x.EffDate.Value.ToString("yyyy-MM-dd") : "",
        x.QtyAllocated, x.QtyUsed, remain = x.QtyAllocated - x.QtyUsed, x.Remark
    }).ToListAsync();
    return Results.Ok(new { count = items.Count, totalRemain = items.Sum(i => i.remain), items });
}).RequireAuthorization();

// Cấp định mức KM cho thẻ × chương trình (upsert theo card+program, cộng dồn allocated).
app.MapPost("/api/custpromotions", async (CustPromotionDto dto, AppDbContext db, ITenantContext t) =>
{
    var card = (dto.CardNo ?? "").Trim(); var prog = (dto.ProgramCode ?? "").Trim();
    if (card == "" || prog == "") return Results.BadRequest(new { error = "Thiếu số thẻ hoặc mã chương trình." });
    if (dto.QtyAllocated < 0) return Results.BadRequest(new { error = "Định mức không được âm." });
    var p = await db.CustomerPromotions.FirstOrDefaultAsync(x => x.OrgId == t.OrgId && x.CardNo == card && x.ProgramCode == prog);
    if (p is null) { p = new CustomerPromotion { OrgId = t.OrgId, CardNo = card, ProgramCode = prog }; db.CustomerPromotions.Add(p); }
    p.ProgramName = dto.ProgramName; p.EffDate = dto.EffDate; p.QtyAllocated = dto.QtyAllocated; p.Remark = dto.Remark; p.UpdatedAt = DateTime.Now;
    await db.SaveChangesAsync();
    return Results.Ok(new { p.Id, p.CardNo, p.ProgramCode, remain = p.QtyAllocated - p.QtyUsed });
}).RequireAuthorization();

// Dùng 1 lượt KM: tăng QtyUsed, guard không vượt định mức.
app.MapPost("/api/custpromotions/{id}/use", async (long id, CustPromotionUseDto dto, AppDbContext db, ITenantContext t) =>
{
    var p = await db.CustomerPromotions.FirstOrDefaultAsync(x => x.OrgId == t.OrgId && x.Id == id);
    if (p is null) return Results.NotFound(new { id });
    var n = dto.Qty <= 0 ? 1 : dto.Qty;
    if (p.QtyUsed + n > p.QtyAllocated) return Results.BadRequest(new { error = $"Vượt định mức (còn {p.QtyAllocated - p.QtyUsed})." });
    p.QtyUsed += n; p.UpdatedAt = DateTime.Now;
    await db.SaveChangesAsync();
    return Results.Ok(new { p.Id, p.QtyUsed, remain = p.QtyAllocated - p.QtyUsed });
}).RequireAuthorization();

// ===== Đề nghị giao xe (DeliveryRequest — port 1:1 FrmNewDR/FrmHTCMngDR/FrmDRApproved, 2010.HTC/Sales) =====
app.MapGet("/api/deliveryrequests", async (AppDbContext db, ITenantContext t, string? status, string? dealer) =>
{
    var q = db.DeliveryRequests.Where(x => x.OrgId == t.OrgId);
    if (!string.IsNullOrWhiteSpace(status)) q = q.Where(x => x.Status == status);
    if (!string.IsNullOrWhiteSpace(dealer)) q = q.Where(x => x.DealerCode == dealer);
    var items = await q.OrderByDescending(x => x.Id).Take(500).Select(x => new
    {
        x.Id, x.DRNo, x.DealerCode, requestDate = x.RequestDate.HasValue ? x.RequestDate.Value.ToString("yyyy-MM-dd") : "", x.Status, x.Note,
        cars = db.DeliveryRequestDetails.Count(l => l.OrgId == t.OrgId && l.DeliveryRequestId == x.Id)
    }).ToListAsync();
    return Results.Ok(new { count = items.Count, pending = items.Count(i => i.Status == "Sent"), items });
}).RequireAuthorization();

app.MapPost("/api/deliveryrequests", async (DeliveryRequestDto dto, AppDbContext db, ITenantContext t) =>
{
    var cars = dto.Cars ?? new();
    if (cars.Count == 0) return Results.BadRequest(new { error = "Cần ít nhất 1 xe." });
    var seen = new HashSet<string>(StringComparer.OrdinalIgnoreCase);
    foreach (var c in cars)
    {
        var cid = (c.CarId ?? "").Trim();
        if (cid == "") return Results.BadRequest(new { error = "Có dòng thiếu mã xe." });
        if (!seen.Add(cid)) return Results.BadRequest(new { error = "Trùng mã xe: " + cid });
    }
    var no = "DR" + DateTime.Now.ToString("yyMMddHHmmss");
    var h = new DeliveryRequest { OrgId = t.OrgId, DRNo = no, DealerCode = dto.DealerCode, RequestDate = dto.RequestDate ?? DateTime.Now, Status = "Draft" };
    db.DeliveryRequests.Add(h); await db.SaveChangesAsync();
    foreach (var c in cars)
        db.DeliveryRequestDetails.Add(new DeliveryRequestDetail { OrgId = t.OrgId, DeliveryRequestId = h.Id, CarId = c.CarId!.Trim(), ModelCode = c.ModelCode, DeliveryStartDate = c.DeliveryStartDate, Remark = c.Remark });
    await db.SaveChangesAsync();
    return Results.Ok(new { h.Id, h.DRNo, cars = cars.Count });
}).RequireAuthorization();

app.MapGet("/api/deliveryrequests/{id}/cars", async (long id, AppDbContext db, ITenantContext t) =>
{
    var h = await db.DeliveryRequests.FirstOrDefaultAsync(x => x.OrgId == t.OrgId && x.Id == id);
    if (h is null) return Results.NotFound(new { id });
    var cars = await db.DeliveryRequestDetails.Where(l => l.OrgId == t.OrgId && l.DeliveryRequestId == id)
        .Select(l => new { l.CarId, l.ModelCode, deliveryStartDate = l.DeliveryStartDate.HasValue ? l.DeliveryStartDate.Value.ToString("yyyy-MM-dd") : "", l.Remark }).ToListAsync();
    return Results.Ok(new { h.DRNo, h.DealerCode, h.Status, cars });
}).RequireAuthorization();

app.MapPost("/api/deliveryrequests/{id}/action", async (long id, DRActionDto dto, AppDbContext db, ITenantContext t) =>
{
    var h = await db.DeliveryRequests.FirstOrDefaultAsync(x => x.OrgId == t.OrgId && x.Id == id);
    if (h is null) return Results.NotFound(new { id });
    var act = (dto.Action ?? "").Trim().ToLowerInvariant();
    (string[] from, string to) rule = act switch
    {
        "submit"  => (new[] { "Draft" }, "Sent"),
        "approve" => (new[] { "Sent" }, "Approved"),
        "reject"  => (new[] { "Sent" }, "Rejected"),
        _ => (Array.Empty<string>(), "")
    };
    if (rule.to == "") return Results.BadRequest(new { error = "Hành động không hợp lệ." });
    if (!rule.from.Contains(h.Status)) return Results.BadRequest(new { error = $"Không thể '{act}' khi đang {h.Status}." });
    if (act == "reject" && string.IsNullOrWhiteSpace(dto.Note)) return Results.BadRequest(new { error = "Từ chối phải ghi lý do." });
    h.Status = rule.to; if (!string.IsNullOrWhiteSpace(dto.Note)) h.Note = dto.Note; h.UpdatedAt = DateTime.Now;
    await db.SaveChangesAsync();
    return Results.Ok(new { h.Id, h.Status });
}).RequireAuthorization();

// ===== Dự kiến đơn hàng theo tháng (EstimateOrder — port 1:1 FrmQuanLyDuKienDH, 2010.HTC/Sales) =====
app.MapGet("/api/estimateorders", async (AppDbContext db, ITenantContext t, string? dealer, string? month, string? status) =>
{
    var q = db.EstimateOrders.Where(x => x.OrgId == t.OrgId);
    if (!string.IsNullOrWhiteSpace(dealer)) q = q.Where(x => x.DealerCode == dealer);
    if (!string.IsNullOrWhiteSpace(month)) q = q.Where(x => x.MonthEstimate == month);
    if (!string.IsNullOrWhiteSpace(status)) q = q.Where(x => x.Status == status);
    var items = await q.OrderByDescending(x => x.Id).Take(500).Select(x => new
    {
        x.Id, x.EstOrderNo, x.DealerCode, x.MonthEstimate, x.HtcStaffInCharge, x.Status,
        lines = db.EstimateOrderLines.Count(l => l.OrgId == t.OrgId && l.EstimateOrderId == x.Id),
        totalQty = db.EstimateOrderLines.Where(l => l.OrgId == t.OrgId && l.EstimateOrderId == x.Id).Sum(l => (int?)l.Quantity) ?? 0
    }).ToListAsync();
    return Results.Ok(new { count = items.Count, items });
}).RequireAuthorization();

app.MapPost("/api/estimateorders", async (EstimateOrderDto dto, AppDbContext db, ITenantContext t) =>
{
    if (string.IsNullOrWhiteSpace(dto.MonthEstimate)) return Results.BadRequest(new { error = "Thiếu tháng dự kiến." });
    var lines = dto.Lines ?? new();
    if (lines.Count == 0) return Results.BadRequest(new { error = "Cần ít nhất 1 dòng model." });
    var seen = new HashSet<string>(StringComparer.OrdinalIgnoreCase);
    foreach (var l in lines)
    {
        var mc = (l.ModelCode ?? "").Trim();
        if (mc == "") return Results.BadRequest(new { error = "Có dòng thiếu mã model." });
        if (!seen.Add(mc + "|" + (l.SpecCode ?? ""))) return Results.BadRequest(new { error = "Trùng model+spec: " + mc });
        if (l.Quantity <= 0) return Results.BadRequest(new { error = "Số lượng phải > 0 cho " + mc });
    }
    var no = "EST" + DateTime.Now.ToString("yyMMddHHmmss");
    var h = new EstimateOrder { OrgId = t.OrgId, EstOrderNo = no, DealerCode = dto.DealerCode, MonthEstimate = dto.MonthEstimate, HtcStaffInCharge = dto.HtcStaffInCharge, Status = "Draft" };
    db.EstimateOrders.Add(h); await db.SaveChangesAsync();
    foreach (var l in lines)
        db.EstimateOrderLines.Add(new EstimateOrderLine { OrgId = t.OrgId, EstimateOrderId = h.Id, ModelCode = l.ModelCode!.Trim(), SpecCode = l.SpecCode, Quantity = l.Quantity });
    await db.SaveChangesAsync();
    return Results.Ok(new { h.Id, h.EstOrderNo, lines = lines.Count });
}).RequireAuthorization();

app.MapGet("/api/estimateorders/{id}/lines", async (long id, AppDbContext db, ITenantContext t) =>
{
    var h = await db.EstimateOrders.FirstOrDefaultAsync(x => x.OrgId == t.OrgId && x.Id == id);
    if (h is null) return Results.NotFound(new { id });
    var lines = await db.EstimateOrderLines.Where(l => l.OrgId == t.OrgId && l.EstimateOrderId == id)
        .Select(l => new { l.ModelCode, l.SpecCode, l.Quantity }).ToListAsync();
    return Results.Ok(new { h.EstOrderNo, h.DealerCode, h.MonthEstimate, h.Status, lines });
}).RequireAuthorization();

app.MapPost("/api/estimateorders/{id}/confirm", async (long id, AppDbContext db, ITenantContext t) =>
{
    var h = await db.EstimateOrders.FirstOrDefaultAsync(x => x.OrgId == t.OrgId && x.Id == id);
    if (h is null) return Results.NotFound(new { id });
    if (h.Status == "Confirmed") return Results.BadRequest(new { error = "Đã xác nhận rồi." });
    h.Status = "Confirmed"; await db.SaveChangesAsync();
    return Results.Ok(new { h.Id, h.Status });
}).RequireAuthorization();

