        if (!string.IsNullOrWhiteSpace(p.PackingListNo))
            db.TkhqPLs.Add(new TkhqPL { OrgId = t.OrgId, TkhqId = k.Id, PackingListNo = p.PackingListNo.Trim().ToUpperInvariant(), ShippingDateEnd = p.ShippingDateEnd });
