    var cars = await db.RetrieveReqCars.Where(c => c.OrgId == t.OrgId && c.ReqId == r.Id)
        .Select(c => new { c.Vin, c.StorageCode, c.DtlStatus }).ToListAsync();
    return Results.Ok(new { r.TranspReqNo, r.Status, count = cars.Count, cars });
